// Compile a single morning digest. If there are zero runs, still send a
// 'no runs yet — your seed is the input' note (no shaming).
const rows = $input.all().map(i => i.json);
const hasRows = rows.length > 0;

let body;
if (!hasRows) {
  body = [
    'No report runs in the last 24h.',
    'That is fine — today\'s seed is the input.',
    'Open the app to drop one cycle item.'
  ].join('\n');
} else {
  const lines = rows.slice(0, 5).map(r => {
    const status = r.status === 'failed' ? 'needs-rework' : r.status;
    return `· ${r.report_name} — ${status}` +
           ` (pending ${r.items_pending}, approved ${r.items_approved}, deferred ${r.items_deferred})`;
  });
  body = ['Yesterday\'s reports:', ...lines, '', 'Tap to open: https://kingdom-pwa-node.vercel.app/'].join('\n');
}

const title = 'Daily report · ' + new Date().toLocaleDateString('en-US', { weekday: 'long' });
const url = 'https://kingdom-pwa-node.vercel.app/';

return [{
  json: {
    title,
    body,
    pushover: { title, message: body, priority: 0, url_title: 'Open dashboard', url },
    email:    { subject: title, text: body + '\n\n' + url }
  }
}];
